body.script:
//
(function () {
  var REPO = 'sample-works/amo-picked-website';
  var FALLBACK_REF = '3701da1';
  function boot(ref) {
    var base = 'https://cdn.jsdelivr.net/gh/' + REPO + '@' + ref;
    var css = document.createElement('link');
    css.rel = 'stylesheet';
    css.href = base + '/styles.css';
    var loaded = false;
    function loadApp() {
      if (loaded) return;
      loaded = true;
      var js = document.createElement('script');
      js.src = base + '/app.js';
      document.body.appendChild(js);
    }
    css.onload = loadApp;
    css.onerror = loadApp;
    document.head.appendChild(css);
    setTimeout(loadApp, 1500);
  }
  var timer = setTimeout(function () {
    timer = null;
    boot(FALLBACK_REF);
  }, 1200);
  fetch('https://api.github.com/repos/' + REPO + '/commits/main')
    .then(function (r) { return r.ok ? r.json() : Promise.reject(); })
    .then(function (d) {
      if (!timer) return;
      clearTimeout(timer);
      timer = null;
      boot((d && d.sha) ? d.sha : FALLBACK_REF);
    })
    .catch(function () {
      if (!timer) return;
      clearTimeout(timer);
      timer = null;
      boot(FALLBACK_REF);
    });
})();
//
